const { chromium } = require('playwright-core');

const CHROME_PATH = '/opt/ms-playwright/chromium-1234/chrome-linux/chrome';

(async () => {
  const browser = await chromium.launch({
    executablePath: CHROME_PATH,
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));

  async function shot(name) {
    await page.screenshot({ path: `/tmp/pw-test/${name}.png` });
    console.log('screenshot ->', name);
  }

  console.log('--- movie list (today, likely empty) ---');
  await page.goto('http://localhost:4200/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await shot('01-today');
  console.log(await page.locator('[data-testid]').count(), 'elements with data-testid');

  console.log('--- movie list with date 2026-09-15 ---');
  await page.goto('http://localhost:4200/?date=2026-09-15', { waitUntil: 'networkidle' });
  await page.waitForSelector('[data-testid="movie-card"]', { timeout: 5000 });
  await shot('02-sep15');
  const cardCount = await page.locator('[data-testid="movie-card"]').count();
  console.log('movie cards:', cardCount);

  console.log('--- click first screening ---');
  await page.locator('[data-testid="screening-button"]').first().click();
  await page.waitForURL(/\/screenings\/\d+\/seats/);
  await page.waitForSelector('[data-testid="seat-map"]');
  await shot('03-seats');
  const seatCount = await page.locator('[data-testid="seat"]').count();
  const couchCount = await page.locator('[data-testid="couch"]').count();
  console.log('seats:', seatCount, 'couches:', couchCount);

  console.log('--- select some seats ---');
  const available = page.locator('[data-testid="seat"][data-state="available"]');
  for (let i = 0; i < 3; i++) {
    await available.nth(i).click();
  }
  await page.locator('[data-testid="couch"][data-state="available"]').first().click();
  await shot('04-selected');
  console.log('selected-seats-count text:', await page.locator('[data-testid="selected-seats-count"]').textContent());

  console.log('--- continue to summary ---');
  await page.locator('[data-testid="continue-button"]').click();
  await page.waitForURL(/\/screenings\/\d+\/summary/);
  await shot('05-summary');
  console.log('total:', await page.locator('[data-testid="summary-total"]').textContent());

  console.log('--- confirm to checkout ---');
  await page.locator('[data-testid="confirm-button"]').click();
  await page.waitForURL(/\/screenings\/\d+\/checkout/);
  await shot('06-checkout');

  console.log('--- submit invalid form ---');
  await page.locator('[data-testid="pay-button"]').click();
  await page.waitForTimeout(300);
  await shot('07-checkout-invalid');
  console.log('toast:', await page.locator('[data-testid="toast"]').textContent().catch(() => null));

  console.log('--- fill valid form and pay ---');
  await page.locator('[data-testid="first-name-input"]').fill('Anna');
  await page.locator('[data-testid="last-name-input"]').fill('Kowalska');
  await page.locator('[data-testid="email-input"]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid="confirm-email-input"]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid="phone-input"]').fill('123456789');
  await page.locator('[data-testid="terms-checkbox"]').click();
  await shot('08-checkout-filled');
  await page.locator('[data-testid="pay-button"]').click();
  await page.waitForURL(/\/confirmation/, { timeout: 5000 });
  await shot('09-confirmation');
  console.log('confirmation message:', await page.locator('[data-testid="confirmation-message"]').textContent());

  console.log('--- console errors ---');
  console.log(errors.length ? errors.join('\n') : 'none');

  await browser.close();
})().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

