const { chromium } = require('playwright-core');

const CHROME_PATH = '/opt/ms-playwright/chromium-1234/chrome-linux/chrome';

function safeClick(page, selector, timeout = 3000) {
  return page.locator(selector).click({ timeout }).catch((e) => {
    console.log('  (click reported:', e.message.split('\n')[0], ')');
  });
}

(async () => {
  const browser = await chromium.launch({ executablePath: CHROME_PATH, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  await page.route(/fonts\.(googleapis|gstatic)\.com/, (route) => route.abort());
  page.on('pageerror', (err) => console.log('PAGEERROR', err.message));
  page.on('close', () => console.log('EVENT: page closed unexpectedly'));

  async function shot(name) {
    await page.screenshot({ path: `/tmp/pw-test/${name}.png` }).catch((e) => console.log('shot failed', e.message));
    console.log('screenshot ->', name);
  }

  console.log('--- seat map ---');
  await page.goto('http://localhost:4200/screenings/1/seats', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('[data-testid="seat-map"]');
  await page.locator('[data-testid="seat"][data-state="available"]').first().click();
  await page.locator('[data-testid="seat"][data-state="available"]').nth(1).click();
  await page.locator('[data-testid="couch"][data-state="available"]').first().click();
  await shot('c1-seats');

  console.log('--- continue to summary ---');
  await safeClick(page, '[data-testid="continue-button"]');
  await page.waitForURL(/\/summary/, { timeout: 10000 });
  await page.waitForSelector('[data-testid="summary-total"]');
  console.log('total:', await page.locator('[data-testid="summary-total"]').textContent());
  await shot('c2-summary');

  console.log('--- confirm to checkout ---');
  await safeClick(page, '[data-testid="confirm-button"]');
  await page.waitForURL(/\/checkout/, { timeout: 10000 });
  await page.waitForSelector('[data-testid="first-name-input"]');
  await shot('c3-checkout');

  console.log('--- submit invalid (empty) form ---');
  await safeClick(page, '[data-testid="pay-button"]');
  await page.waitForTimeout(400);
  const toastText = await page.locator('[data-testid="toast"]').textContent().catch(() => null);
  console.log('toast:', toastText);
  await shot('c4-invalid');

  console.log('--- fill valid form ---');
  await page.locator('[data-testid="first-name-input"]').fill('Anna');
  await page.locator('[data-testid="last-name-input"]').fill('Kowalska');
  await page.locator('[data-testid="email-input"]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid="confirm-email-input"]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid="phone-input"]').fill('123456789');
  await page.locator('[data-testid="terms-checkbox"]').click();
  await shot('c5-filled');

  console.log('--- pay ---');
  await safeClick(page, '[data-testid="pay-button"]');
  await page.waitForURL(/\/confirmation/, { timeout: 10000 });
  await page.waitForSelector('[data-testid="confirmation-message"]');
  console.log('confirmation:', await page.locator('[data-testid="confirmation-message"]').textContent());
  await shot('c6-confirmation');

  console.log('ALL GOOD');
  await browser.close();
})().catch((e) => {
  console.error('FATAL', e.message);
  process.exit(1);
});

